/**
 * CONCEPT 09 - Christmas Countdown / Unwrap the Season
 * Original, asset-free 2D Canvas animation. Duration: 25 seconds. Scenes: 3.
 * Reference: 3840 x 2160, 16:9, 60 fps; proportionally scales to FHD and 2K.
 * Time is supplied in SECONDS. Each file is a separate, complete draw entry point.
 * No DOM, external assets/libraries, humans, animals, glow, bloom or 3D objects.
 * Artistic gradient and background decoration remain completely static.
 * Host encoder target/minimum: 100,000,000 bits per second (100 Mbps).
 * Canvas draws frames; the host renderer must enforce the export video bitrate.
 */
function draw(ctx, time, width, height) {

  if (!ctx || !Number.isFinite(time) || !(width > 0) || !(height > 0)) return;
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, minSide / 1080);
  const localT = sceneProgress * sceneDuration;
  const TAU = Math.PI * 2;
  const cycle = TAU * loopT / duration;
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { v = clamp(v); return v * v * v * (v * (v * 6 - 15) + 10); };
  const progress = (a, b) => ease((localT - a) / (b - a));
  const mix = (a, b, v) => a + (b - a) * v;
  const rgba = (r, g, b, a) => 'rgba(' + r + ',' + g + ',' + b + ',' + clamp(a) + ')';
  function colorMix(a, b, v) {
    const aa = parseInt(a.slice(1), 16), bb = parseInt(b.slice(1), 16);
    return '#' + [16, 8, 0].map(s => Math.round(mix((aa >> s) & 255, (bb >> s) & 255, clamp(v))).toString(16).padStart(2, '0')).join('');
  }
  function rr(x, y, w, h, r, fill, stroke, lw = 2) {
    if (!(w > 0 && h > 0)) return;
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function circle(x, y, r, fill, stroke, lw = 2) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, stroke, lw = 2) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke();
  }
  function polygon(points, fill, stroke, lw = 2) {
    ctx.beginPath(); points.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function star(x, y, r, fill, stroke, angle = -Math.PI / 2, points = 5) {
    const p = [];
    for (let i = 0; i < points * 2; i++) {
      const a = angle + i * Math.PI / points, d = i % 2 ? r * 0.46 : r;
      p.push([x + Math.cos(a) * d, y + Math.sin(a) * d]);
    }
    polygon(p, fill, stroke, 2.2);
  }
  function snowflake(x, y, r, stroke, angle = 0, lw = 2) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = i * Math.PI / 3, c = Math.cos(a), s = Math.sin(a);
      ctx.moveTo(0, 0); ctx.lineTo(r * c, r * s);
      for (const side of [-1, 1]) {
        const b = a + side * Math.PI / 3;
        ctx.moveTo(r * 0.56 * c, r * 0.56 * s);
        ctx.lineTo(r * 0.56 * c + Math.cos(b) * r * 0.23, r * 0.56 * s + Math.sin(b) * r * 0.23);
      }
    }
    ctx.stroke(); ctx.restore();
  }
  function text(str, x, y, size, color, maxW, align = 'left', weight = 500) {
    ctx.save(); ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.font = weight + ' ' + size + 'px sans-serif';
    const measured = ctx.measureText(str).width;
    if (maxW && measured > maxW) { size *= maxW / measured; ctx.font = weight + ' ' + size + 'px sans-serif'; }
    ctx.fillStyle = color; ctx.fillText(str, x, y); ctx.restore();
  }
  function tracked(str, x, y, size, spacing, color, center = false) {
    ctx.save(); ctx.font = '600 ' + size + 'px sans-serif'; ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';
    const widths = Array.from(str).map(ch => ctx.measureText(ch).width);
    const total = widths.reduce((a, b) => a + b, 0) + spacing * Math.max(0, widths.length - 1);
    let cursor = center ? x - total / 2 : x; ctx.fillStyle = color;
    Array.from(str).forEach((ch, i) => { ctx.fillText(ch, cursor, y); cursor += widths[i] + spacing; }); ctx.restore();
  }
  function group(x, y, rotation, opacity, fn) {
    if (opacity <= 0) return;
    ctx.save(); ctx.translate(x, y); ctx.rotate(rotation); ctx.globalAlpha *= clamp(opacity); fn(); ctx.restore();
  }
  function bow(x, y, size, fill, stroke, reveal = 1) {
    if (reveal <= 0) return;
    ctx.save(); ctx.translate(x, y); ctx.globalAlpha *= clamp(reveal);
    for (const side of [-1, 1]) {
      ctx.save(); ctx.scale(side, 1);
      ctx.beginPath(); ctx.moveTo(0, 0);
      ctx.bezierCurveTo(size * 0.17, -size * 0.47, size * 0.91, -size * 0.87, size, -size * 0.37);
      ctx.bezierCurveTo(size * 1.06, size * 0.04, size * 0.43, size * 0.17, 0, 0); ctx.closePath();
      ctx.fillStyle = fill; ctx.fill(); ctx.strokeStyle = stroke; ctx.lineWidth = 2.4; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(size * 0.13, -size * 0.05); ctx.quadraticCurveTo(size * 0.46, -size * 0.25, size * 0.75, -size * 0.31);
      ctx.strokeStyle = stroke; ctx.lineWidth = 1.6; ctx.stroke(); ctx.restore();
    }
    rr(-size * 0.14, -size * 0.17, size * 0.28, size * 0.31, size * 0.08, fill, stroke, 2.3);
    ctx.restore();
  }
  function ribbonWipe(fill, edge) {
    const d = 0.56;
    let x, w;
    if (localT < d) { x = mix(-8, 1928, ease(localT / d)); w = 1936 - x; }
    else if (localT > sceneDuration - d) { x = -8; w = mix(0, 1936, ease((localT - (sceneDuration - d)) / d)); }
    else return;
    ctx.save(); ctx.fillStyle = fill; ctx.fillRect(x, -12, w, 1104);
    // This opaque, full-frame ribbon hides scene handoffs; it is not a background animation.
    ctx.beginPath(); ctx.rect(x, -12, w, 1104); ctx.clip();
    for (let i = 0; i < 3; i++) line(0, 488 + i * 51, 1920, 488 + i * 51, edge, i === 1 ? 2.2 : 1.1);
    snowflake(960, 540, 25, edge, 0, 2.1);
    ctx.restore();
  }
  ctx.save();
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0; ctx.shadowColor = 'transparent';
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]); ctx.lineDashOffset = 0; ctx.lineCap = 'round'; ctx.lineJoin = 'round';

  const C={ink:'#294c40',cream:'#f5edda',gold:'#d4ba88',sage:'#a9bea4',mint:'#c9d7b9',red:'#a96373',muted:'#d3ddc6'};
  const bg=ctx.createLinearGradient(0,0,width,height);
  bg.addColorStop(0,'#25443e');bg.addColorStop(.54,'#4b7161');bg.addColorStop(1,'#92b098');
  ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);
  ctx.translate(width/2,height/2);ctx.scale(scale,scale);ctx.translate(-960,-540);

  // Gradient, frame, circles and etched decoration are invariant throughout the clip.
  line(130,75,1790,75,'#8fa990',1.2);line(130,1007,1790,1007,'#8fa990',1.2);
  line(130,1033,220,1033,C.gold,2);line(1700,1033,1790,1033,C.gold,2);
  snowflake(1742,165,26,'#b3c09f',Math.PI/6,1.4);snowflake(154,927,17,'#a6b89b',0,1.3);
  circle(1806,592,49,null,'#91ac94',1.2);circle(112,532,35,null,'#759a85',1.2);
  tracked('THE CHRISTMAS COUNTDOWN',145,125,15,3.7,C.gold);
  text('Small surprises. Thoughtful details. A season of joy.',192,976,18,C.muted,1320);
  snowflake(1768,963,12,C.gold,0,1.6);

  function gift(x,base,w,h,fill=C.red){
    group(x,base,0,1,()=>{
      rr(-w/2,-h,w,h,7,fill,C.ink,2.3);
      for(const a of [-.27,.27])for(const b of [-.73,-.30])star(a*w,b*h,Math.min(w,h)*.035,C.cream,null,-Math.PI/2,4);
      rr(-w*.06,-h,w*.12,h,0,C.gold,null);rr(-w/2,-h*.48,w,h*.11,0,C.gold,null);
      if(w>70){
        ctx.save();ctx.setLineDash([2,8]);ctx.lineDashOffset=-loopT*3;
        line(-w*.04,-h+3,-w*.04,-3,C.ink,1.0);ctx.restore();
      }
      rr(-w/2-6,-h-13,w+12,24,5,fill,C.ink,2.2);rr(-w*.06,-h-12,w*.12,22,0,C.gold,null);
      bow(0,-h-13,w*.21,C.gold,C.ink);
    });
  }
  function bauble(x,y,r,fill=C.red,rotation=0){
    group(x,y,rotation,1,()=>{
      rr(-r*.19,-r-13,r*.38,14,3,C.gold,C.ink,1.7);
      circle(0,0,r,fill,C.ink,2.2);circle(0,0,r*.77,null,C.cream,1.4);
      snowflake(0,0,r*.51,C.cream,.025*Math.sin(cycle*2),1.6);
    });
  }
  function pendant(x,anchor,drop,r,id){
    group(x,anchor,.022*Math.sin(cycle*1.5+id),1,()=>{
      line(0,0,0,drop-r-12,C.gold,1.7);bauble(0,drop,r,id%2?C.sage:C.red,0);
    });
  }
  function surprise(x,y,size,kind){
    if(kind%3===0){
      gift(x,y+size*.42,size*.98,size*.76,C.red);
    }else if(kind%3===1){
      bauble(x,y+size*.08,size*.49,C.sage,.02*Math.sin(cycle*1.5+kind));
    }else{
      star(x,y,size*.59,C.gold,C.ink,-Math.PI/2+.024*Math.sin(cycle*1.5+kind),5);
      star(x,y,size*.32,null,C.cream,-Math.PI/2+.024*Math.sin(cycle*1.5+kind),5);
    }
  }
  function slidingWindow(x,y,w,h,opened,kind,large=false){
    rr(x,y,w,h,7,'#e6d9b8',C.ink,1.6);
    ctx.save();ctx.beginPath();ctx.rect(x+2,y+2,w-4,h-4);ctx.clip();
    surprise(x+w/2,y+h*.53,Math.min(w,h)*(large?.74:.52),kind);
    const shift=(w+4)*clamp(opened),fill=kind%2?C.sage:C.mint;
    rr(x+shift,y,w,h,5,fill,C.ink,1.6);
    // Printed motifs belong to the sliding paper panel; none spill into a neighbour.
    for(let i=0;i<3;i++)line(x+shift+w*.20,y+h*(.28+i*.22),x+shift+w*.80,y+h*(.28+i*.22),colorMix(fill,C.cream,.52),large?2.1:1.2);
    circle(x+shift+12,y+h/2,large?4:2.5,C.ink);
    ctx.restore();
  }
  function dayTile(x,y,date,opened,arrival){
    const p=ease(arrival);
    group(x,y+(1-p)*13,0,p,()=>{
      const fill=date===25?C.red:C.cream;
      rr(0,0,182,88,8,fill,C.ink,1.9);
      text(String(date).padStart(2,'0'),40,55,29,date===25?C.cream:C.ink,58,'center',600);
      slidingWindow(81,11,88,66,opened,date%3,false);
    });
  }

  if(currentScene===0){
    text('Unwrap the season.',145,215,68,C.cream,1470,'left',600);
    text('Twenty-five little moments. One wonderful Christmas.',149,260,21,C.muted,1450);
    tracked('DECEMBER',202,388,13,3.2,C.gold);
    text('Every day,',197,456,46,C.cream,420,'left',600);
    text('a little more',197,513,46,C.cream,420,'left',600);
    text('joy.',197,570,46,C.cream,420,'left',600);
    pendant(355,622,137,66,0);
    tracked('COUNTING DOWN TO CHRISTMAS',355,887,10,1.7,C.gold,true);
    rr(690,326,1044,568,15,'#a2b599',C.ink,2.8);
    rr(701,337,1022,546,8,null,C.cream,1.2);
    const chosen=[4,9,12,17,23,24];
    for(let i=0;i<25;i++){
      const idx=chosen.indexOf(i);
      const open=idx<0?0:.95*clamp(progress(1.2+idx*.5,2.0+idx*.5)-progress(4.7+idx*.26,5.5+idx*.26));
      dayTile(713+(i%5)*204,350+Math.floor(i/5)*108,i+1,open,progress(.13+i*.016,1.03+i*.016));
    }
  }else if(currentScene===1){
    text('Three little moments of wonder.',145,215,61,C.cream,1490,'left',600);
    text('A little gift, a festive detail and a wish for tomorrow.',149,260,21,C.muted,1450);
    const labels=['A LITTLE GIFT','A FESTIVE DETAIL','A WISH FOR TOMORROW'];
    for(let i=0;i<3;i++){
      const x=225+i*515,y=421,p=progress(.13+i*.12,1.01+i*.12);
      group(x,y+(1-p)*17,0,p,()=>{
        rr(0,0,440,362,13,C.cream,C.ink,2.6);
        text(String(22+i),65,66,47,C.ink,94,'center',600);
        tracked('DEC',361,57,12,2.2,C.ink,true);
        line(25,91,415,91,C.gold,1.4);
        const opened=clamp(progress(.9+i*1.75,2.0+i*1.75)-progress(6.25+i*.22,7.25+i*.22));
        slidingWindow(24,112,392,186,opened,i,true);
        tracked(labels[i],220,334,11,1.7,C.ink,true);
      });
    }
    tracked('ONE DAY CLOSER TO CHRISTMAS',960,878,13,3.0,C.gold,true);
  }else{
    text('Christmas is here.',960,211,70,C.cream,1450,'center',600);
    tracked('THE LITTLE THINGS MAKE THE SEASON.',960,260,14,3.0,C.gold,true);
    const arrive=progress(.13,1.05);
    group(960,606+(1-arrive)*18,0,arrive,()=>{
      const paper=ctx.createLinearGradient(-250,-220,250,220);paper.addColorStop(0,C.cream);paper.addColorStop(1,'#e9dfc5');
      rr(-270,-240,540,480,13,paper,C.ink,2.8);
      rr(-252,-222,504,444,6,null,C.gold,1.5);
      star(0,-181,25,C.gold,C.ink,-Math.PI/2,5);
      text('25',0,-15,148,C.ink,450,'center',600);
      tracked('DECEMBER',0,44,15,4.3,C.ink,true);
      tracked('MERRY CHRISTMAS',0,133,19,3.1,C.red,true);
      for(const side of [-1,1])snowflake(side*101,184,14,C.red,0,1.6);
      ctx.save();ctx.setLineDash([2,9]);ctx.lineDashOffset=-loopT*3;
      line(-225,213,225,213,C.red,1.5);ctx.restore();
    });
    gift(420,846,250,230,C.red);gift(1500,846,250,260,C.sage);
    pendant(420,330,100,47,1);pendant(1500,330,100,47,2);
    text('A season of little wonders.',960,927,17,C.muted,850,'center',500);
  }
  ribbonWipe('#e6e0c8','#719177');
  ctx.restore();

}
draw.duration = 25;
draw.fps = 60;
draw.bitrate = 100000000;
draw.renderSettings = Object.freeze({
  duration: 25, sceneCount: 3, width: 3840, height: 2160,
  fps: 60, videoBitrate: 100000000, minimumVideoBitrate: 100000000,
  seamlessLoop: true
});

