    ctx.fillStyle = color; ctx.fillText(str, x, y); ctx.restore();
  }
  function tracked(str, x, y, size, spacing, color, center = false) {
    ctx.save(); ctx.font = '600 ' + size + 'px sans-serif'; ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';
    const widths = Array.from(str).map(ch => ctx.measureText(ch).width);
    const total = widths.reduce((a, b) => a + b, 0) + spacing * Math.max(0, widths.length - 1);
    let cursor = center ? x - total / 2 : x; ctx.fillStyle = color;
    Array.from(str).forEach((ch, i) => { ctx.fillText(ch, cursor, y); cursor += widths[i] + spacing; }); ctx.restore();
  }
  function group(x, y, rotation, opacity, fn) {
    if (opacity <= 0) return;
    ctx.save(); ctx.translate(x, y); ctx.rotate(rotation); ctx.globalAlpha *= clamp(opacity); fn(); ctx.restore();
  }
  function bow(x, y, size, fill, stroke, reveal = 1) {
    if (reveal <= 0) return;
